export const GENERATING_SOLUTIONS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Lebih dari satu solusi",q:"Setelah memahami sebuah masalah, langkah yang baik SEBELUM memilih apa yang dilakukan adalah...",options:["Menghasilkan beberapa kemungkinan solusi dulu, lalu membandingkannya","Menunggu orang lain memutuskan apa yang harus dilakukan, lalu mengikuti saja keputusan mereka","Langsung mengambil ide pertama yang muncul di kepala tanpa membandingkannya dengan kemungkinan lain"],answer:0,explain:"Ide pertama jarang yang terbaik. Punya beberapa pilihan memberi bahan untuk memilih.",hint:"Apakah kamu membeli baju pertama yang kamu lihat, atau melihat beberapa dulu?"},
{n:2,type:"mcq",micro:"Curah gagasan",q:"'Curah gagasan' (brainstorming) adalah kegiatan untuk...",options:["Mengkritik setiap ide yang disebutkan orang lain supaya ide yang jelek cepat tersingkir dari daftar","Menghasilkan sebanyak mungkin ide dulu, tanpa menilai baik-buruknya saat itu juga","Memilih satu ide saja secepatnya lalu berhenti, supaya kelompok tidak berlama-lama berdiskusi lagi"],answer:1,explain:"Aturan curah gagasan: kejar jumlah, tunda penilaian. Menilai sambil menghasilkan membuat ide berani cepat mati.",hint:"Fase 'menghasilkan' dan fase 'menilai' dipisah — mana yang lebih dulu?"},
{n:3,type:"tf",micro:"Menunda penilaian",q:"Benar atau Salah: Saat curah gagasan, sebaiknya kita langsung mengkritik setiap ide begitu diucapkan agar cepat menemukan yang terbaik.",answer:false,explain:"Kritik dini membuat orang takut mengusulkan ide tidak biasa. Kumpulkan dulu semua ide, nilai belakangan.",hint:"Apa yang terjadi pada ide berani kalau langsung dikritik?"},
{n:4,type:"mcq",micro:"Kuantitas dulu",q:"Mengapa mengejar BANYAK ide (bahkan yang aneh) berguna?",options:["Semakin banyak ide yang muncul justru semakin membingungkan, sehingga tidak ada manfaatnya sama sekali","Ide yang aneh selalu menjadi ide terbaik, sehingga ide yang biasa sebaiknya langsung dibuang saja","Ide aneh kadang mengandung benih ide bagus, dan banyak pilihan memberi ruang memilih"],answer:2,explain:"Beberapa ide terbaik lahir dari mengubah atau menggabungkan ide yang awalnya terlihat konyol.",hint:"Dari 20 ide, berapa peluang menemukan yang bagus dibanding dari 2 ide?"},
{n:5,type:"mcq",micro:"Membangun di atas ide orang lain",q:"Dalam curah gagasan kelompok, respons yang paling membantu terhadap ide teman:",options:["'Ya, dan kita bisa menambah...' — mengembangkan idenya","'Ide saya jauh lebih bagus daripada ide kamu, jadi sebaiknya kita pakai ide saya saja.'","'Itu tidak akan berhasil, jadi lebih baik kamu memikirkan ide lain yang lebih masuk akal.'"],answer:0,explain:"'Ya, dan...' menjaga aliran ide dan sering menghasilkan gabungan yang lebih baik daripada ide-ide terpisah.",hint:"Mana yang menambah bahan bakar ke api ide, dan mana yang memadamkannya?"},
{n:6,type:"mcq",micro:"Ide dari sudut berbeda",q:"Untuk 'membuat kelas lebih rapi', mendapatkan ide dari beberapa sudut berarti bertanya...",options:["'Apakah kelas ini sebenarnya perlu dirapikan, atau lebih baik dibiarkan seperti keadaannya sekarang?'","'Apa yang bisa diubah dari perabotnya? Dari kebiasaannya? Dari aturannya? Dari tata letaknya?'","'Siapa yang paling berantakan di kelas ini, sehingga dia yang harus dimarahi dan diberi hukuman?'"],answer:1,explain:"Melihat masalah dari beberapa 'lensa' (benda, perilaku, aturan, ruang) memunculkan jenis solusi yang berbeda-beda.",hint:"Sudut pandang berbeda membuka jenis ide yang berbeda."},
{n:7,type:"mcq",micro:"Ide yang jelas vs ide yang perlu digali",q:"Setelah ide-ide 'jelas' habis (biasanya 3–5 pertama), melanjutkan curah gagasan penting karena...",options:["Setelah lima ide pertama, sisa ide yang muncul pasti jelek, sehingga tidak perlu dicatat lagi","Sebaiknya curah gagasan berhenti pada ide kelima, karena ide setelahnya pasti membuang waktu kelompok","Ide yang lebih kreatif dan tidak biasa sering muncul setelah ide-ide yang mudah habis"],answer:2,explain:"Ide-ide pertama adalah yang 'sudah ada di permukaan'. Ide segar butuh dorongan untuk terus menggali.",hint:"Kapan ide yang benar-benar baru biasanya muncul — di awal atau setelah yang mudah habis?"},
{n:8,type:"order",micro:"Alur menghasilkan lalu memilih",q:"Urutkan langkah dari masalah yang sudah dipahami sampai solusi terpilih.",items:["Hasilkan banyak ide solusi tanpa menilai","Kelompokkan & perjelas ide-ide yang mirip","Nilai ide dengan kriteria (biaya, waktu, dampak, kemudahan)","Pilih satu (atau gabungan) untuk dicoba"],answer:[0,1,2,3],explain:"Hasilkan → rapikan → nilai → pilih. Fase 'melebar' (banyak ide) mendahului fase 'menyempit' (memilih).",hint:"Kamu tidak bisa memilih dari daftar yang belum dibuat."},
{n:9,type:"mcq",micro:"Ide 'buruk' sebagai batu loncatan",q:"Untuk 'mengurangi antrean kantin', seseorang usul 'hapus kantin'. Ide ini tidak akan dipakai, tapi bisa berguna karena...",options:["Memicu pertanyaan: 'bagaimana kalau makanan datang ke kelas?' → ide layanan antar per kelas","Ide yang buruk tidak pernah berguna sama sekali, sehingga sebaiknya langsung dilupakan oleh seluruh kelompok","Ide itu berarti kantin memang sebaiknya benar-benar dihapus supaya tidak ada lagi antrean di sekolah"],answer:0,explain:"Ide ekstrem sering membuka arah pemikiran baru yang menghasilkan solusi yang bisa dijalankan.",hint:"Ide 'hapus kantin' mendorong kita membayangkan cara lain makanan sampai ke siswa."},
{n:10,type:"mcq",micro:"Menuliskan semua ide",q:"Menuliskan setiap ide (bukan hanya mengandalkan ingatan) saat curah gagasan penting karena...",options:["Hanya untuk formalitas saja supaya terlihat rapi, padahal ide bisa diingat dengan baik tanpa dicatat","Ide yang tidak dicatat mudah hilang, dan daftar tertulis memudahkan membandingkan nanti","Membuat kegiatan menjadi lebih lama tanpa guna, karena menulis memakan waktu dan tidak menambah ide"],answer:1,explain:"Ide datang cepat dan mudah terlupa. Catatan menjaga semuanya untuk tahap penilaian.",hint:"Bisakah kamu mengingat 15 ide yang diucapkan cepat dalam 10 menit?"},
{n:11,type:"mcq",micro:"Ide sendiri dulu, baru kelompok",q:"Sering lebih banyak ide muncul kalau tiap orang menuliskan idenya sendiri dulu SEBELUM diskusi kelompok, karena...",options:["Diskusi kelompok tidak berguna sama sekali, sehingga sebaiknya semua ide hanya dikumpulkan secara tertulis","Menulis sendiri selalu lebih lambat daripada berbicara, sehingga hasil akhirnya pasti lebih sedikit ide","Menghindari semua orang hanya mengikuti ide pertama yang diucapkan dengan lantang"],answer:2,explain:"Menulis sendiri dulu mencegah 'penjangkaran' pada ide pertama dan memberi ruang bagi yang pemalu.",hint:"Apa yang terjadi kalau satu orang lantang mengucapkan ide di awal?"},
{n:12,type:"mcq",micro:"Kriteria memilih",q:"'Kriteria' untuk memilih solusi adalah...",options:["Hal-hal yang kita pakai untuk menilai dan membandingkan ide, misalnya biaya, waktu, dampak, keamanan","Nama-nama ide","Perasaan tentang masalah"],answer:0,explain:"Kriteria yang jelas membuat pemilihan lebih adil dan bisa dijelaskan, bukan sekadar 'aku suka yang ini'.",hint:"Bagaimana kamu membandingkan dua ide secara adil?"},
{n:13,type:"tf",micro:"Solusi bisa digabung",q:"Benar atau Salah: Kamu harus selalu memilih tepat satu ide utuh dari daftar; menggabungkan bagian dari beberapa ide tidak diperbolehkan.",answer:false,explain:"Justru kadang solusi terbaik adalah gabungan: ambil 'sistem nomor antrean' dari satu ide dan 'buka jalur kedua' dari ide lain menjadi satu solusi.",hint:"Apakah kamu harus memilih tepat satu ide dari daftar?"},
{n:14,type:"mcq",micro:"Ide yang belum tentu bisa",q:"Ide 'sewa 10 robot untuk membersihkan sekolah' mungkin bagus dampaknya tapi gugur saat dinilai karena...",options:["Ide bersih selalu ditolak","Tidak realistis dengan anggaran dan sumber daya sekolah","Robot itu jelek"],answer:1,explain:"Menilai ide berarti mengecek kelayakan (bisa dijalankan dengan sumber daya nyata), bukan hanya dampak.",hint:"Apakah sekolah punya uang untuk 10 robot?"},
{n:15,type:"mcq",micro:"Jangan langsung jatuh cinta pada satu ide",q:"Bahaya 'jatuh cinta' pada ide pertama yang kamu suka:",options:["Tidak ada bahaya sama sekali kalau kamu menyukainya, karena ide yang kamu suka pasti ide yang terbaik","Ide pertama selalu merupakan ide terbaik, sehingga mencari ide lain hanya akan membuang waktu saja","Kamu berhenti mencari, dan mungkin melewatkan ide yang lebih baik atau lebih mudah"],answer:2,explain:"Keterikatan dini menutup pintu untuk pilihan lain. Tetap terbuka sampai kamu benar-benar membandingkan.",hint:"Apa yang berhenti kamu lakukan begitu kamu 'yakin' pada satu ide?"},
{n:16,type:"mcq",micro:"Ide dari orang yang terdampak",q:"Untuk memecahkan masalah yang memengaruhi kelompok tertentu (misalnya siswa kelas 1 kesulitan menemukan kelas), sumber ide yang berharga:",options:["Bertanya langsung ke siswa kelas 1 dan mengamati mereka","Hanya bertanya ke guru","Menebak sendiri"],answer:0,explain:"Orang yang mengalami masalah sering punya ide praktis yang tidak terpikir dari luar.",hint:"Siapa yang paling tahu di mana kesulitannya?"},
{n:17,type:"mcq",micro:"Ide meniru dari tempat lain",q:"Untuk 'membuat perpustakaan lebih menarik', sumber ide yang berguna:",options:["Tidak boleh meniru siapa pun, karena ide yang bagus harus selalu berasal sepenuhnya dari kepalamu sendiri","Lihat bagaimana toko buku, kafe, atau perpustakaan lain menata ruang dan kegiatannya","Hanya memikirkannya sendirian di dalam kamar, tanpa melihat tempat lain atau bertanya kepada siapa pun"],answer:1,explain:"Meniru & menyesuaikan ide yang berhasil di tempat lain adalah cara cepat menghasilkan solusi.",hint:"Siapa yang sudah menyelesaikan masalah mirip, dan bagaimana caranya?"},
{n:18,type:"mcq",micro:"Waktu untuk menghasilkan ide",q:"Menetapkan waktu khusus (misalnya '10 menit hanya untuk ide, belum menilai') membantu karena...",options:["Membuang 10 menit","Ide harus selalu instan","Memberi izin untuk berpikir bebas tanpa buru-buru menghakimi, lalu penilaian dapat gilirannya sendiri"],answer:2,explain:"Memisahkan waktu 'menghasilkan' dari 'menilai' membuat kedua fase berjalan lebih baik.",hint:"Bisakah kamu berkreasi dan mengkritik dengan baik pada saat yang sama?"},
{n:19,type:"mcq",micro:"Ide vs solusi lengkap",q:"Sebuah 'ide' pada tahap ini boleh berupa...",options:["Kalimat singkat arah solusi ('sistem piket berpasangan'), belum perlu rincian penuh","Rencana lengkap dua puluh langkah yang sudah memuat siapa, kapan, dan berapa biayanya untuk setiap bagian","Hanya ide yang sudah pasti berhasil, karena ide yang belum pasti tidak boleh ditulis dalam daftar"],answer:0,explain:"Pada tahap menghasilkan, ide cukup berupa arah. Rincian menyusul setelah ide terpilih.",hint:"Apakah setiap ide harus sudah jadi rencana lengkap untuk ditulis?"},
{n:20,type:"open",micro:"Curah gagasan sendiri",q:"Masalah: 'Banyak siswa lupa membawa alat kebersihan saat jadwal piket.' Tuliskan minimal 6 ide solusi yang berbeda, tanpa menilai baik-buruknya. Sertakan minimal 1 ide yang terasa 'agak liar'.",explain:"Jawaban baik: 6+ ide yang benar-benar berbeda (bukan variasi tipis), penilaian ditunda, dan ada satu ide berani.",hint:"Ubah sudut: benda, pengingat, kebiasaan, aturan, kepemilikan alat.",sample:"Contoh: (1) sediakan set alat kebersihan tetap di kelas, disimpan di loker khusus; (2) pengingat di grup kelas malam sebelumnya; (3) papan jadwal piket besar di pintu keluar; (4) piket berpasangan agar saling mengingatkan; (5) sanksi ringan yang disepakati (piket dua kali); (6) [liar] pasang 'gerbang piket' — yang piket tidak boleh pulang sebelum tugas selesai, alat dipinjam dari pos satpam; (7) rotasi: alat kebersihan 'diwariskan' dari petugas hari ini ke petugas besok secara langsung."},
{n:21,type:"mcq",micro:"Teknik: ubah kata kerja",q:"Teknik 'ubah kata kerja' untuk masalah 'menyimpan buku': ganti 'menyimpan' dengan 'menggantung', 'melipat', 'membagi', 'memajang'. Gunanya:",options:["Tidak ada gunanya","Memaksa memunculkan ide yang tidak akan terpikir dengan kata kerja aslinya","Mengubah masalahnya jadi lain"],answer:1,explain:"Mengganti kata kerja inti membuka jenis solusi baru (rak gantung, buku terlipat kompak, dsb.).",hint:"Apa ide baru muncul dari 'menggantung buku' dibanding 'menyimpan buku'?"},
{n:22,type:"mcq",micro:"Teknik: dan sebaliknya",q:"Teknik 'balik masalah': alih-alih 'bagaimana membuat siswa datang tepat waktu', tanya 'bagaimana membuat siswa PASTI terlambat'. Gunanya:",options:["Untuk benar-benar membuat orang terlambat","Membingungkan saja","Daftar 'penyebab terlambat' yang muncul langsung menunjukkan hal-hal yang perlu dihilangkan"],answer:2,explain:"Membalik masalah memunculkan daftar penyebab, dan tiap penyebab adalah petunjuk solusi (hilangkan/kurangi penyebab itu).",hint:"Kalau kamu tahu semua cara membuat orang terlambat, apa yang kamu lakukan dengan daftar itu?"},
{n:23,type:"mcq",micro:"Teknik: kombinasikan",q:"Teknik 'gabungkan dua ide': 'aplikasi pengingat' + 'papan fisik' menjadi...",options:["Papan fisik dengan kode QR yang membuka pengingat di ponsel","Dua hal terpisah yang tidak berhubungan, jadi tetap dikerjakan sendiri-sendiri tanpa pernah digabungkan","Hanya salah satu dari keduanya saja yang dipakai, sedangkan yang lain dibuang dan dilupakan begitu saja"],answer:0,explain:"Menggabungkan kekuatan dua ide sering menghasilkan solusi yang lebih baik dari keduanya sendiri-sendiri.",hint:"Apa jadinya kalau kekuatan papan (terlihat) digabung kekuatan aplikasi (mengingatkan aktif)?"},
{n:24,type:"mcq",micro:"Teknik: pemicu acak",q:"Memakai kata acak ('payung') untuk memicu ide solusi masalah 'kelas berisik' bisa menghasilkan...",options:["Payung untuk setiap siswa supaya mereka tidak kehujanan di kelas, padahal tidak ada hubungannya dengan berisik","'Payung' → melindungi → 'zona tenang' terlindung di sudut kelas untuk yang butuh fokus","Tidak mungkin menghasilkan apa-apa, karena kata acak tidak punya hubungan apa pun dengan masalah yang ada"],answer:1,explain:"Rangsangan acak memaksa otak membuat koneksi baru, kadang menuju ide yang tidak akan muncul lewat jalur biasa.",hint:"Apa sifat payung yang bisa dipinjam untuk masalah kebisingan?"},
{n:25,type:"classify",micro:"Mengelompokkan ide",q:"Untuk masalah 'sampah di kelas', kelompokkan ide ke 'Ubah lingkungan/alat', 'Ubah kebiasaan/aturan', atau 'Ubah informasi/pengingat'.",items:["Tambah tempat sampah di tiap sudut","Buat kesepakatan kelas: buang sampah sebelum bel pulang","Tempel poster lucu tentang membuang sampah","Sediakan tempat sampah pilah warna"],groups:["Ubah lingkungan/alat","Ubah kebiasaan/aturan","Ubah informasi/pengingat"],answer:{"Ubah lingkungan/alat":["Tambah tempat sampah di tiap sudut","Sediakan tempat sampah pilah warna"],"Ubah kebiasaan/aturan":["Buat kesepakatan kelas: buang sampah sebelum bel pulang"],"Ubah informasi/pengingat":["Tempel poster lucu tentang membuang sampah"]},explain:"Mengelompokkan ide berdasarkan 'jenis perubahan' membantu melihat apakah kamu sudah mengeksplorasi semua jalur.",hint:"Apakah ide ini mengubah benda, perilaku, atau info?"},
{n:26,type:"mcq",micro:"Menemukan celah dalam daftar ide",q:"Setelah mengelompokkan ide dan melihat semua ide masuk kategori 'tambah alat', ini menunjukkan...",options:["Kategori lain tidak penting","Sudah cukup","Kamu belum mengeksplorasi jalur lain (ubah kebiasaan, ubah aturan, ubah info) — kembali hasilkan ide di kategori itu"],answer:2,explain:"Pengelompokan mengungkap 'kebutaan': jenis solusi yang belum dipikirkan sama sekali.",hint:"Kalau semua ide sejenis, jenis apa yang belum kamu coba?"},
{n:27,type:"mcq",micro:"Menyaring awal (bukan penilaian penuh)",q:"Penyaringan awal sebuah daftar 20 ide bertujuan...",options:["Menghapus ide yang jelas tidak mungkin (melanggar hukum, jauh di luar anggaran) agar tersisa ~5–8 kandidat untuk dinilai serius","Langsung memilih 1","Menghapus semua ide berani"],answer:0,explain:"Saring dulu yang jelas gugur, sisakan sedikit kandidat kuat untuk penilaian mendalam.",hint:"Apa yang bisa dicoret cepat tanpa analisis panjang?"},
{n:28,type:"tf",micro:"Ide liar disaring belakangan",q:"Benar atau Salah: Begitu sebuah ide terdengar liar, sebaiknya langsung dibuang saat itu juga supaya daftar ide tetap rapi.",answer:false,explain:"Banyak ide liar mengandung inti yang berharga. Biarkan masuk daftar dan baru dinilai (atau diubah jadi versi yang bisa dijalankan) pada tahap penilaian.",hint:"Kapan sebaiknya ide liar dinilai — saat diucapkan atau nanti?"},
{n:29,type:"mcq",micro:"Ukuran daftar ide",q:"Untuk masalah kelas sedang, jumlah ide yang wajar dikumpulkan sebelum menyaring:",options:["Ratusan, tidak boleh berhenti","Sekitar 10–20 ide beragam","Tepat 2"],answer:1,explain:"Cukup banyak untuk memberi pilihan nyata dan memunculkan ide segar, tanpa menjadi tak terkelola.",hint:"Berapa banyak yang memberi pilihan bagus tanpa membuat penilaian mustahil?"},
{n:30,type:"order",micro:"Dari daftar panjang ke kandidat",q:"Urutkan langkah mengubah 20 ide menjadi 3 kandidat.",items:["Gabungkan ide yang mirip, perjelas maksud tiap ide","Coret ide yang jelas melanggar batasan (biaya/aturan/waktu)","Nilai sisanya dengan 2–3 kriteria utama","Pilih 2–3 kandidat teratas untuk dianalisis lebih dalam"],answer:[0,1,2,3],explain:"Rapikan → saring kasar → nilai dengan kriteria → pilih kandidat.",hint:"Rapikan daftar sebelum menyaring."},
{n:31,type:"mcq",micro:"Ide yang menyelesaikan gejala vs akar",q:"Untuk 'lantai kelas sering licin karena atap bocor', ide 'pasang keset besar' menangani...",options:["Akar masalah sepenuhnya, sehingga setelah keset dipasang atap tidak perlu diperbaiki lagi oleh siapa pun","Tidak ada hubungannya dengan masalah lantai licin, karena keset hanya berguna untuk membersihkan sepatu","Gejala (licin), bukan akar (bocor) — berguna sementara, tapi akar tetap perlu ditangani"],answer:2,explain:"Saat menilai ide, perhatikan apakah ia mengatasi akar atau hanya meredakan gejala. Keduanya bisa berguna pada tempatnya.",hint:"Apakah keset menghentikan air masuk?"},
{n:32,type:"mcq",micro:"Ide yang menciptakan masalah baru",q:"Ide 'kunci gerbang saat jam pelajaran agar tidak ada yang keluar' perlu dinilai hati-hati karena...",options:["Bisa menciptakan masalah baru (bahaya saat darurat, siswa terkunci di luar)","Selalu ide bagus","Tidak mungkin ada efek samping"],answer:0,explain:"Setiap solusi bisa punya efek samping. Menilai ide termasuk memikirkan 'apa lagi yang berubah kalau ini dilakukan'.",hint:"Apa yang terjadi kalau ada kebakaran dan gerbang terkunci?"},
{n:33,type:"mcq",micro:"Menjaga keberagaman kandidat",q:"Saat memilih 3 kandidat dari daftar, sebaiknya mereka...",options:["Dipilih acak","Cukup berbeda satu sama lain (bukan 3 versi ide yang hampir sama), agar pilihan benar-benar berarti","Ketiganya hampir identik"],answer:1,explain:"Tiga kandidat yang mirip bukan pilihan nyata. Keberagaman membuat perbandingan bermakna.",hint:"Apa gunanya memilih di antara 3 hal yang hampir sama?"},
{n:34,type:"mcq",micro:"Ide reversibel vs sulit dibatalkan",q:"Saat menilai, membedakan ide yang 'mudah dibatalkan kalau gagal' dari yang 'sulit dibatalkan' berguna karena...",options:["Tidak ada bedanya","Yang sulit dibatalkan selalu lebih baik","Ide yang mudah dibatalkan bisa dicoba dengan risiko rendah; yang sulit dibatalkan butuh keyakinan lebih"],answer:2,explain:"Untuk ide berisiko rendah dan mudah dibatalkan, 'coba dulu' sering lebih baik daripada analisis panjang.",hint:"Mana yang lebih aman dicoba: mengubah tata letak kursi, atau mengecat seluruh dinding?"},
{n:35,type:"mcq",micro:"Ide dari menggabungkan orang berbeda",q:"Curah gagasan dengan orang dari latar berbeda (usia, minat, peran) cenderung menghasilkan...",options:["Ragam ide yang lebih luas karena tiap orang membawa pengalaman dan sudut pandang berbeda","Ide yang sama saja","Lebih sedikit ide"],answer:0,explain:"Keberagaman peserta memperluas ruang ide karena masing-masing 'melihat' masalah secara berbeda.",hint:"Apakah 5 orang yang berpikir mirip menghasilkan ide seluas 5 orang yang berbeda?"},
{n:36,type:"mcq",micro:"Menghidupkan kembali curah gagasan yang macet",q:"Kalau ide berhenti mengalir, cara menghidupkannya kembali:",options:["Menyalahkan peserta","Ganti teknik (balik masalah, pemicu acak, ubah kata kerja) atau ubah lensa (benda/perilaku/aturan)","Berhenti dan ambil ide yang ada"],answer:1,explain:"Kebuntuan ide biasanya berarti perlu rangsangan atau sudut pandang baru, bukan berhenti.",hint:"Apa yang bisa memaksa otak membuat koneksi baru?"},
{n:37,type:"tf",micro:"Tidak semua masalah butuh 20 ide",q:"Benar atau Salah: Untuk masalah kecil dan mendesak, menghasilkan 2–3 ide lalu memilih sudah cukup — tidak perlu curah gagasan panjang.",answer:true,explain:"Skala usaha menghasilkan ide sebaiknya sepadan dengan besar dan pentingnya masalah.",hint:"Apakah memilih makan siang butuh 20 ide?"},
{n:38,type:"mcq",micro:"Ide yang membutuhkan izin/pihak lain",q:"Ide 'ubah jam masuk sekolah' saat dinilai perlu diberi catatan...",options:["Bisa langsung dilakukan besok pagi oleh kelas sendiri, tanpa menunggu keputusan dari pihak mana pun","Tidak perlu izin siapa pun, karena jam masuk sekolah boleh diatur sendiri oleh tiap kelas sesuai keinginan","Butuh keputusan pihak berwenang (kepala sekolah, dinas) — di luar kendali kelas sepenuhnya"],answer:2,explain:"Menilai ide termasuk mengecek siapa yang harus setuju dan apakah itu realistis dalam waktu yang ada.",hint:"Siapa yang harus mengiyakan sebelum ide ini bisa jalan?"},
{n:39,type:"mcq",micro:"Menyimpan ide yang tidak dipakai",q:"Ide bagus yang tidak dipilih sekarang sebaiknya...",options:["Disimpan dalam catatan — bisa berguna untuk masalah lain atau ketika keadaan berubah","Dibuang total","Dirahasiakan"],answer:0,explain:"Ide yang tidak cocok sekarang bisa jadi solusi tepat nanti. Menyimpannya menghemat kerja di masa depan.",hint:"Apakah ide yang tidak dipakai hari ini pasti tidak berguna selamanya?"},
{n:40,type:"open",micro:"Menerapkan teknik menghasilkan ide",q:"Masalah: 'Perpustakaan sekolah sepi.' Gunakan minimal 3 teknik berbeda (balik masalah, ubah kata kerja, gabungkan ide, pemicu acak, tiru dari tempat lain) untuk menghasilkan total minimal 8 ide. Tandai teknik mana menghasilkan ide mana.",explain:"Jawaban baik: minimal 3 teknik dipakai secara eksplisit, menghasilkan 8+ ide yang beragam, dengan teknik ditandai.",hint:"Tiap teknik memaksa cara berpikir yang berbeda — pakai bergantian.",sample:"Balik masalah ('bagaimana membuat perpustakaan PASTI sepi'): jam buka bentrok istirahat, tidak ada yang tahu koleksinya, suasananya kaku → ide: sesuaikan jam buka, buat 'rak rekomendasi minggu ini', kursi santai. Ubah kata kerja ('membaca' → 'berkumpul', 'bermain', 'membuat'): klub baca, sudut permainan papan, pojok kerajinan dari buku bekas. Tiru tempat lain (kafe/toko buku): musik lembut pelan, papan tulis 'buku favoritku', pameran sampul menghadap depan. Gabungkan (pengumuman + hadiah): tantangan baca bulanan dengan papan peringkat kelas."},
{n:41,type:"mcq",micro:"Matriks keputusan",q:"'Matriks keputusan' adalah tabel dengan...",options:["Gambar masalah","Ide di baris, kriteria di kolom, dan skor di tiap sel — untuk membandingkan pilihan secara sistematis","Daftar nama"],answer:1,explain:"Matriks keputusan membuat perbandingan terlihat: tiap ide dinilai pada tiap kriteria, lalu skornya dijumlahkan.",hint:"Bagaimana membandingkan 4 ide pada 4 kriteria sekaligus tanpa bingung?"},
{n:42,type:"mcq",micro:"Memilih kriteria",q:"Kriteria untuk menilai solusi sebaiknya...",options:["Sebanyak mungkin","Hanya 'apakah aku suka'","Sedikit tapi penting (3–5), bisa dinilai, dan mencerminkan apa yang benar-benar penting untuk masalah ini"],answer:2,explain:"Terlalu banyak kriteria membuat penilaian melelahkan; yang penting adalah kriteria yang benar-benar membedakan pilihan.",hint:"Kriteria mana yang benar-benar menentukan solusi ini berhasil atau tidak?"},
{n:43,type:"mcq",micro:"Bobot kriteria",q:"Memberi 'bobot' pada kriteria (misalnya keamanan × 3, biaya × 2, keindahan × 1) berarti...",options:["Kriteria yang lebih penting berpengaruh lebih besar pada skor akhir","Semua kriteria tetap dianggap sama pentingnya, sehingga angka pengali itu tidak mengubah skor akhir sedikit pun","Kriteria dengan bobot kecil sama sekali diabaikan, sehingga keindahan tidak boleh dinilai sedikit pun"],answer:0,explain:"Bobot mencerminkan bahwa tidak semua kriteria sama pentingnya. Keamanan mungkin jauh lebih penting dari keindahan.",hint:"Apakah 'hemat Rp10.000' sepenting 'aman dari cedera'?"},
{n:44,type:"mcq",micro:"Trade-off",q:"'Trade-off' antara dua solusi berarti...",options:["Salah satu solusi sempurna di semua kriteria, sehingga solusi yang lain pasti harus dibuang seluruhnya","Solusi A lebih baik pada satu kriteria (misalnya lebih murah) tapi lebih buruk pada kriteria lain (misalnya lebih lambat)","Kedua solusi sama persis di semua kriteria, sehingga memilih yang mana pun hasilnya tidak berbeda sama sekali"],answer:1,explain:"Hampir setiap pilihan nyata melibatkan trade-off. Memilih berarti memutuskan pertukaran mana yang bisa diterima.",hint:"Apakah biasanya ada satu pilihan yang menang di SEMUA hal?"},
{n:45,type:"mcq",micro:"Membaca matriks keputusan",q:"Dalam matriks, ide A skor total 18, ide B skor 17, ide C skor 11. Kesimpulan yang tepat:",options:["A pasti yang terbaik, karena selisih satu angka saja sudah cukup untuk menentukan pilihan secara mutlak","Pilih C karena sangat berbeda dari yang lain, sebab ide yang skornya paling rendah pasti paling kreatif","A dan B hampir setara (perlu pertimbangan lebih, misalnya kriteria yang tidak masuk matriks); C jelas tertinggal"],answer:2,explain:"Selisih skor kecil berarti 'hampir seri' — matriks membantu menyempit, bukan menggantikan pertimbangan akhir. Selisih besar (C) lebih meyakinkan.",hint:"Apakah selisih 1 poin cukup untuk yakin, dibanding selisih 6 poin?"},
{n:46,type:"mcq",micro:"Kriteria yang wajib (bukan skor)",q:"Beberapa kriteria bersifat 'lolos/gagal', bukan skor — misalnya 'harus aman untuk anak'. Ide yang gagal di kriteria wajib...",options:["Langsung gugur, tidak peduli seberapa tinggi skornya di kriteria lain","Tetap bisa menang kalau skor lain tinggi","Diberi bonus"],answer:0,explain:"Kriteria wajib (syarat mutlak) memfilter dulu; hanya ide yang lolos semua syarat mutlak yang dinilai lebih lanjut.",hint:"Bisakah solusi yang tidak aman menang hanya karena murah dan cepat?"},
{n:47,type:"order",micro:"Memilih dengan matriks keputusan",q:"Urutkan langkah memakai matriks keputusan.",items:["Tetapkan kriteria dan bobotnya, serta syarat wajib bila ada","Buang ide yang gagal syarat wajib","Beri skor tiap ide pada tiap kriteria, kalikan bobot, jumlahkan","Tinjau hasil: kalau ada yang hampir seri, pakai pertimbangan tambahan sebelum memutuskan"],answer:[0,1,2,3],explain:"Kriteria & bobot → filter syarat wajib → skor berbobot → tinjau & putuskan.",hint:"Kamu perlu kriteria sebelum bisa memberi skor."},
{n:48,type:"mcq",micro:"Skor yang jujur",q:"Saat memberi skor ide dalam matriks, godaan yang harus dihindari:",options:["Menilai ide hanya dari pendapat teman yang paling keras bersuara, tanpa mempertimbangkan bukti sama sekali","Diam-diam memberi skor tinggi ke ide favoritmu agar 'menang', bukan menilai apa adanya","Memberi skor terlalu rendah ke semua ide supaya matriks terlihat ketat, tanpa membedakan mutunya"],answer:1,explain:"Matriks hanya berguna kalau skornya jujur. Kalau kamu 'menyetel' skor untuk hasil yang kamu mau, alatnya jadi sia-sia.",hint:"Untuk apa memakai matriks kalau kamu memaksa hasilnya?"},
{n:49,type:"mcq",micro:"Kapan matriks terlalu berat",q:"Untuk keputusan kecil sehari-hari, membuat matriks keputusan formal...",options:["Selalu wajib","Satu-satunya cara memilih","Berlebihan; perbandingan cepat 2–3 kriteria di kepala sudah cukup"],answer:2,explain:"Alat formal untuk keputusan besar/rumit; untuk yang kecil, pertimbangan cepat lebih efisien.",hint:"Apakah memilih pensil butuh tabel skor?"},
{n:50,type:"mcq",micro:"Solusi 'cukup baik' vs 'sempurna'",q:"Menunggu menemukan solusi yang sempurna di semua kriteria sering...",options:["Membuat kita tidak pernah bertindak; solusi 'cukup baik' yang bisa dijalankan sekarang sering lebih berharga","Adalah satu-satunya pilihan yang bijak, sehingga kita harus terus menunggu sampai solusi sempurna ditemukan","Menjamin hasil yang terbaik, karena solusi yang sempurna di semua kriteria pasti mudah dijalankan sekarang"],answer:0,explain:"Solusi sempurna jarang ada. 'Cukup baik dan bisa dijalankan' yang diperbaiki sambil jalan biasanya mengalahkan menunggu kesempurnaan.",hint:"Mana yang lebih baik: rencana 80% sekarang atau rencana 100% yang tak pernah dimulai?"},
{n:51,type:"open",micro:"Membuat matriks keputusan",q:"Masalah 'memilih kegiatan penggalangan dana kelas'. Kandidat: (A) bazar makanan, (B) cuci sepatu berbayar, (C) jual kerajinan. Buat matriks: pilih 3–4 kriteria dengan bobot, beri skor 1–5 tiap kandidat, hitung total, dan tulis kesimpulan termasuk trade-off.",explain:"Jawaban baik: kriteria relevan berbobot, skor masuk akal, perhitungan benar, dan menyebut trade-off pemenang.",hint:"Pilih kriteria yang benar-benar membedakan ketiga pilihan.",sample:"Kriteria (bobot): potensi untung (×3), kemudahan pelaksanaan (×2), jumlah siswa yang bisa terlibat (×2), risiko/izin (×1, skor tinggi = risiko rendah). A bazar: untung 5, mudah 3, keterlibatan 5, risiko 3 → 15+6+10+3 = 34. B cuci sepatu: untung 3, mudah 4, keterlibatan 3, risiko 4 → 9+8+6+4 = 27. C kerajinan: untung 3, mudah 3, keterlibatan 4, risiko 5 → 9+6+8+5 = 28. Kesimpulan: A unggul terutama karena potensi untung dan keterlibatan tinggi; trade-off-nya butuh persiapan lebih dan izin penggunaan dapur/area. B dan C hampir seri sebagai alternatif kalau izin bazar sulit."},
{n:52,type:"mcq",micro:"Kriteria yang terlewat",q:"Setelah matriks memilih ide A, seorang anggota berkata 'tapi A membuat kelas sebelah terganggu'. Respons yang tepat:",options:["Buang seluruh matriks dan mulai dari awal tanpa membahas lagi apa yang sebenarnya telah dinilai tadi","Tambahkan kriteria 'dampak ke pihak lain' dan nilai ulang — matriks awal melewatkan sesuatu yang penting","Abaikan saja keberatan itu, karena matriks sudah memutuskan dan hasil perhitungan tidak boleh diubah lagi"],answer:1,explain:"Matriks sebaik kriteria yang dipilih. Kalau kriteria penting terlewat, tambahkan dan hitung ulang, jangan buta pada hasil.",hint:"Apakah hasil matriks lebih penting daripada dampak nyata yang terlewat?"},
{n:53,type:"tf",micro:"Memilih adalah komitmen sementara",q:"Benar atau Salah: Begitu satu solusi dipilih untuk dicoba, kandidat lain hilang selamanya dan tidak boleh dipakai lagi walau solusi terpilih gagal.",answer:false,explain:"Memilih adalah keputusan untuk mencoba dulu, bukan janji abadi. Kalau yang dipilih gagal, daftar kandidat lain tetap tersedia untuk dicoba.",hint:"Kalau solusi A dicoba dan gagal, apakah B dan C lenyap?"},
{n:54,type:"mcq",micro:"Memilih untuk kelompok",q:"Saat kelompok harus memilih dan pendapat terbelah, cara yang adil dan berguna:",options:["Ikuti yang paling senior","Undi tanpa diskusi","Sepakati kriteria bersama dulu, nilai bersama, lalu putuskan berdasarkan hasil — bukan berdasarkan siapa paling keras bersuara"],answer:2,explain:"Menyepakati kriteria SEBELUM menilai mengurangi perdebatan berbasis ego dan membuat keputusan bisa dijelaskan.",hint:"Apa yang mengurangi 'menang karena paling lantang'?"},
{n:55,type:"mcq",micro:"Solusi dengan ketidakpastian",q:"Ide A hasilnya pasti sedang; ide B mungkin hebat atau mungkin gagal total. Memilih di antaranya bergantung pada...",options:["Seberapa besar taruhannya dan apakah kamu mampu menanggung kegagalan B — kalau gagal B berat, A yang aman lebih bijak","Selalu pilih yang berisiko, karena hasil yang mungkin hebat pasti lebih baik daripada hasil yang sedang","Selalu pilih yang aman, karena kemungkinan gagal tidak pernah layak dipertaruhkan dalam keadaan apa pun"],answer:0,explain:"Pilihan berisiko-tinggi cocok bila kegagalannya bisa ditanggung dan potensi hasilnya sepadan; jika tidak, pilih yang lebih pasti.",hint:"Apa akibat terburuk kalau B gagal, dan bisakah kamu menanggungnya?"},
{n:56,type:"mcq",micro:"Uji kecil sebelum komit penuh",q:"Sebelum menerapkan solusi terpilih ke seluruh sekolah, menjalankan 'uji coba di satu kelas' berguna karena...",options:["Uji coba tidak pernah mewakili","Mengungkap masalah nyata dengan risiko kecil, dan hasilnya bisa memperbaiki solusi sebelum skala penuh","Membuang waktu"],answer:1,explain:"Uji coba (pilot) adalah cara murah menguji pilihan sebelum berkomitmen besar.",hint:"Lebih baik menemukan cacat solusi di 1 kelas atau di 20 kelas sekaligus?"},
{n:57,type:"tf",micro:"Kriteria berubah seiring pemahaman",q:"Benar atau Salah: Daftar kriteria boleh diperbarui jika, saat menilai ide, kamu menyadari ada faktor penting yang belum masuk.",answer:true,explain:"Menilai ide sering memperjelas apa yang sebenarnya penting. Memperbarui kriteria lalu menilai ulang lebih baik daripada memaksakan daftar awal.",hint:"Apakah daftar kriteria pertama pasti lengkap?"},
{n:58,type:"mcq",micro:"Solusi yang menyenangkan semua pihak",q:"Mencari solusi yang 'menang-menang' (memenuhi kebutuhan beberapa pihak sekaligus) daripada solusi yang 'satu pihak menang, satu kalah':",options:["Selalu mustahil","Selalu kompromi yang lemah","Sering butuh lebih kreativitas, tapi menghasilkan solusi yang lebih tahan lama dan diterima"],answer:2,explain:"Solusi yang mengakomodasi kebutuhan inti beberapa pihak cenderung lebih didukung dan bertahan.",hint:"Solusi mana yang lebih mungkin dijalankan bersama: yang menguntungkan semua, atau yang membuat sebagian pihak kalah?"},
{n:59,type:"mcq",micro:"Memutuskan untuk tidak memutuskan sekarang",q:"Kadang keputusan terbaik adalah 'tunda dan kumpulkan info lebih dulu'. Ini tepat ketika...",options:["Keputusannya besar & sulit dibatalkan, dan informasi tambahan penting bisa didapat dalam waktu wajar","Selalu — menunda selalu lebih baik","Tidak pernah tepat"],answer:0,explain:"Untuk keputusan berdampak besar dan sulit dibalik, menunggu info kunci bisa lebih bijak — asal penundaannya tidak jadi cara menghindar.",hint:"Kapan menunggu info sepadan: keputusan kecil yang mudah dibatalkan, atau besar dan permanen?"},
{n:60,type:"open",micro:"Memilih dan membenarkan",q:"Dari 3 solusi masalah 'kelas panas dan pengap': (A) beli 2 kipas angin (Rp300.000), (B) atur jadwal buka semua jendela + pindahkan lemari yang menghalangi ventilasi (gratis), (C) usul ke sekolah pasang AC (mahal, lama, perlu izin). Pilih satu untuk DICOBA DULU, jelaskan pakai kriteria, sebutkan trade-off, dan rencana kalau gagal.",explain:"Jawaban baik: memilih opsi murah-cepat-reversibel untuk diuji, menilai dengan kriteria eksplisit, mengakui keterbatasannya, dan menyiapkan langkah lanjutan.",hint:"Mulai dari yang paling murah, cepat, dan mudah dibatalkan; siapkan langkah berikutnya.",sample:"Pilih B untuk dicoba dulu. Kriteria: biaya (B gratis, menang), kecepatan (B bisa besok, menang), dampak (B sedang — mungkin tidak cukup di siang terpanas), reversibilitas (B mudah dibatalkan). Trade-off: B mungkin tidak menyelesaikan sepenuhnya di jam 12–14. Rencana kalau gagal: setelah 1 minggu, kalau suhu masih mengganggu, lanjut ke A (kipas) memakai iuran kecil atau dana kelas; C (AC) diajukan sebagai usulan jangka panjang paralel karena butuh waktu lama apa pun hasilnya."},
{n:61,type:"mcq",micro:"Bias 'ide milikku'",q:"Kecenderungan menilai ide sendiri lebih tinggi daripada ide orang lain disebut bias kepemilikan. Cara mengurangi:",options:["Buang semua ide orang lain","Nilai ide tanpa nama pengusulnya (anonim), atau minta orang lain menilai idemu","Selalu pilih idemu"],answer:1,explain:"Menyembunyikan asal ide saat penilaian membuat penilaian lebih fokus pada isi, bukan siapa yang mengusulkan.",hint:"Apa yang membuat penilaian lebih adil terhadap ide dari orang lain?"},
{n:62,type:"mcq",micro:"Solusi yang terlihat sibuk",q:"Tim memilih solusi paling rumit dan mengesankan ('sistem poin digital dengan aplikasi') padahal solusi sederhana ('papan bintang') cukup. Ini contoh...",options:["Pilihan yang selalu benar","Tidak ada masalah","Tertarik pada solusi yang terlihat canggih daripada yang efektif; kesederhanaan sering lebih baik"],answer:2,explain:"Solusi rumit terasa 'serius' tapi sering lebih mahal, lebih rapuh, dan lebih sulit dijalankan. Nilai efektivitas, bukan kesan.",hint:"Apakah solusi yang lebih rumit otomatis lebih baik?"},
{n:63,type:"tf",micro:"Ide pertama bisa saja yang terbaik",q:"Benar atau Salah: Meskipun ide pertama sering bukan yang terbaik, setelah membandingkan beberapa pilihan kadang ternyata ide pertama memang pilihan terbaik.",answer:true,explain:"Tujuan menghasilkan banyak ide bukan untuk menolak ide pertama, melainkan memastikan pilihan dibuat dengan pembanding. Kadang yang pertama tetap menang.",hint:"Apakah 'jangan langsung ambil ide pertama' berarti 'ide pertama pasti salah'?"},
{n:64,type:"mcq",micro:"Solusi yang memindahkan biaya ke orang lain",q:"Ide 'siswa piket membersihkan sampah kelas lain juga' menyelesaikan masalah kelasmu tapi...",options:["Memindahkan beban ke siswa piket secara tidak adil — solusi yang membebani pihak lain perlu ditimbang ulang","Sempurna karena kelasmu bersih","Selalu diterima"],answer:0,explain:"Solusi yang 'berhasil' dengan cara memindahkan beban atau kerugian ke pihak lain sering tidak adil dan tidak bertahan.",hint:"Siapa yang menanggung biaya solusi ini, dan apakah adil?"},
{n:65,type:"mcq",micro:"Terlalu banyak pilihan",q:"Dihadapkan pada 30 ide tanpa penyaringan, orang sering...",options:["Menikmati kebebasan penuh memilih dari semua ide, karena makin banyak pilihan makin mudah menentukan","Kewalahan dan akhirnya memilih asal atau menunda — karena itu daftar perlu disaring dulu jadi sedikit kandidat","Memilih dengan sangat baik, karena tiga puluh ide selalu cukup untuk menemukan yang paling tepat saja"],answer:1,explain:"Terlalu banyak pilihan bisa melumpuhkan. Menyaring menjadi 3–5 kandidat kuat membuat keputusan lebih baik.",hint:"Lebih mudah memilih di antara 3 atau 30?"},
{n:66,type:"tf",micro:"Kreativitas butuh batasan",q:"Benar atau Salah: Batasan seperti 'anggaran nol' atau 'hanya pakai bahan bekas' selalu mematikan kreativitas dan tidak pernah membantu memunculkan ide.",answer:false,explain:"Sebaliknya, batasan sering memicu solusi kreatif: ruang yang sempit memaksa otak mencari jalan tidak biasa. 'Kebebasan tanpa batas' kadang malah membuat bingung.",hint:"Apakah lebih mudah berkreasi dengan 'buat apa saja' atau 'buat sesuatu dari 3 barang ini'?"},
{n:67,type:"mcq",micro:"Solusi yang mengabaikan penyebab",q:"Untuk 'siswa sering bertengkar saat antre', memilih solusi 'pasang CCTV dan hukum yang bertengkar' tanpa menanyakan MENGAPA mereka bertengkar berisiko...",options:["Menyelesaikan segalanya","Selalu berhasil","Tidak menyentuh penyebab (antre terlalu lama, tidak ada aturan giliran) sehingga masalah berlanjut dalam bentuk lain"],answer:2,explain:"Solusi yang dipilih tanpa memahami penyebab sering hanya menekan gejala.",hint:"Apakah menghukum menghilangkan alasan orang bertengkar?"},
{n:68,type:"mcq",micro:"Menilai dampak jangka panjang",q:"Solusi 'beri hadiah besar tiap kali kelas rapi' bisa efektif jangka pendek tapi perlu dinilai jangka panjang karena...",options:["Bisa membuat siswa hanya rapi demi hadiah, dan berhenti begitu hadiah dihentikan","Hadiah selalu menjadi solusi terbaik untuk semua masalah, sehingga tidak perlu dinilai efeknya lagi nanti","Tidak ada efek jangka panjang sama sekali, karena kebiasaan siswa tidak berubah oleh hadiah dalam bentuk apa pun"],answer:0,explain:"Menilai solusi termasuk memikirkan 'apa yang terjadi setelah 3 bulan' dan 'apa yang terjadi kalau ini dihentikan'.",hint:"Apa yang terjadi pada kebiasaan rapi ketika hadiahnya berhenti?"},
{n:69,type:"mcq",micro:"Solusi yang benar untuk masalah yang salah",q:"Tim menghabiskan waktu memilih 'aplikasi absensi terbaik' padahal masalah sebenarnya adalah 'siswa tidak tahu jadwal berubah'. Pelajaran:",options:["Pilihan tidak pernah salah selama dipilih dengan teliti, walaupun masalah yang dipecahkan bukan masalah sebenarnya","Sebelum menghasilkan & memilih solusi, pastikan kamu memecahkan masalah yang benar","Aplikasi absensi memang yang paling penting untuk sekolah, sehingga masalah jadwal tidak perlu dipikirkan lagi"],answer:1,explain:"Solusi terbaik untuk masalah yang salah tetap tidak menyelesaikan apa pun. Kembali ke 'apa masalah sebenarnya'.",hint:"Apakah aplikasi absensi membantu orang tahu jadwal berubah?"},
{n:70,type:"order",micro:"Memeriksa solusi terpilih sebelum melaksanakan",q:"Urutkan pertanyaan pemeriksa untuk solusi yang baru dipilih.",items:["Apakah ini menyelesaikan masalah SEBENARNYA (akar, bukan hanya gejala)?","Apa efek samping atau masalah baru yang mungkin muncul?","Siapa yang menanggung biayanya, dan apakah adil?","Apa yang terjadi dalam jangka panjang / kalau solusi ini dihentikan?"],answer:[0,1,2,3],explain:"Cek: menyelesaikan akar? efek samping? keadilan biaya? ketahanan jangka panjang?",hint:"Mulai dari yang paling mendasar: apakah ini benar-benar menyelesaikan masalahnya?"},
{n:71,type:"mcq",micro:"Konsensus semu",q:"Dalam rapat, tidak ada yang membantah usul ketua, jadi dianggap 'semua setuju'. Risikonya:",options:["Diam selalu berarti setuju","Ketua selalu benar","Diam bukan berarti setuju — bisa jadi orang segan bicara; keputusan terlihat bulat padahal rapuh"],answer:2,explain:"Meminta pendapat tiap orang secara aktif (atau anonim) mengungkap keberatan yang tidak terucap.",hint:"Mengapa seseorang mungkin diam meski tidak setuju?"},
{n:72,type:"mcq",micro:"Menyeimbangkan kreativitas dan kelayakan",q:"Solusi ideal biasanya berada di titik...",options:["Cukup kreatif untuk benar-benar mengatasi masalah, cukup layak untuk dijalankan dengan sumber daya nyata","Sekreatif mungkin, sedangkan kelayakan tidak penting, sebab ide yang unik pasti akan menemukan jalannya sendiri","Selayak mungkin dan semudah mungkin, sedangkan kreativitas tidak penting, karena yang biasa pasti paling aman"],answer:0,explain:"Ide brilian yang tak bisa dijalankan tidak menolong; ide mudah yang tak menyelesaikan masalah juga tidak. Titik temunya yang dicari.",hint:"Apa gunanya ide hebat yang mustahil dilakukan?"},
{n:73,type:"tf",micro:"Memilih perlu keberanian",q:"Benar atau Salah: Pada titik tertentu, terus mencari ide dan menganalisis menjadi cara menghindari keputusan; memilih membutuhkan keberanian untuk berkomitmen meski tidak ada kepastian penuh.",answer:true,explain:"Semua keputusan nyata dibuat dengan informasi tidak lengkap. Menunggu kepastian sempurna sering berarti tidak pernah memutuskan.",hint:"Kapan 'mari kumpulkan lebih banyak ide' berubah menjadi menunda?"},
{n:74,type:"mcq",micro:"Solusi yang tidak bisa diuji",q:"Kalau kamu tidak bisa menentukan 'seperti apa tandanya solusi ini berhasil', maka...",options:["Solusi itu pasti gagal dan sebaiknya segera ditinggalkan, karena solusi tanpa ukuran tidak pernah berhasil","Kamu akan sulit tahu apakah perlu melanjutkan, mengubah, atau mengganti solusi — tetapkan ukuran keberhasilan dulu","Tidak masalah sama sekali, jalankan saja solusinya tanpa mengukur apa pun karena hasilnya akan kelihatan sendiri"],answer:1,explain:"Solusi tanpa ukuran keberhasilan sulit dievaluasi. Sebelum melaksanakan, sepakati bagaimana kamu akan tahu ia bekerja.",hint:"Bagaimana kamu akan tahu solusi ini berhasil atau tidak?"},
{n:75,type:"mcq",micro:"Bias status quo",q:"Kecenderungan memilih 'biarkan seperti sekarang' hanya karena itu yang sudah ada (bukan karena benar-benar terbaik) disebut bias status quo. Cara menyeimbangkan:",options:["Selalu ubah sesuatu","Jangan pernah ubah apa pun","Perlakukan 'tidak berubah' sebagai satu pilihan yang juga dinilai dengan kriteria yang sama, bukan pilihan default otomatis"],answer:2,explain:"'Tetap seperti sekarang' harus bersaing adil dengan pilihan lain, dinilai pada kriteria yang sama.",hint:"Apakah 'tidak berubah' otomatis pilihan terbaik hanya karena paling mudah?"},
{n:76,type:"mcq",micro:"Menghargai ide yang gagal",q:"Sebuah ide dicoba dan tidak berhasil. Sikap yang produktif:",options:["Catat APA yang tidak berhasil dan mengapa — informasi ini menyempit pilihan berikutnya dan berharga","Anggap seluruh proses sia-sia, sehingga semua ide yang sudah dikumpulkan sebaiknya dibuang dan dimulai ulang","Salahkan saja orang yang mengusulkan ide itu, supaya lain kali ia tidak berani mengusulkan ide lagi"],answer:0,explain:"Ide yang gagal tetap memberi data. 'Sekarang kita tahu X tidak jalan karena Y' adalah kemajuan nyata.",hint:"Apa yang kamu pelajari dari percobaan yang gagal?"},
{n:77,type:"tf",micro:"Solusi terbaik bergantung konteks",q:"Benar atau Salah: Solusi yang terbaik untuk satu kelas belum tentu terbaik untuk kelas lain, karena sumber daya, jumlah siswa, dan keadaannya berbeda.",answer:true,explain:"Tidak ada solusi 'terbaik universal'. Pemilihan harus mempertimbangkan konteks spesifik masalah ini.",hint:"Apakah solusi untuk kelas 40 siswa pasti cocok untuk kelas 15 siswa?"},
{n:78,type:"mcq",micro:"Efek samping positif",q:"Saat menilai, memperhatikan efek samping POSITIF (misalnya 'sistem tutor sebaya juga melatih siswa yang mengajar') berguna karena...",options:["Tidak relevan","Sebuah solusi bisa lebih bernilai dari yang terlihat kalau ia membawa manfaat tambahan","Efek samping selalu buruk"],answer:1,explain:"Solusi dengan manfaat sampingan sering merupakan pilihan yang lebih baik pada nilai keseluruhannya.",hint:"Apa lagi hal baik yang ikut terjadi kalau solusi ini dipakai?"},
{n:79,type:"mcq",micro:"Memilih untuk mulai vs memilih untuk selamanya",q:"Kerangka berpikir yang menyehatkan saat memilih solusi untuk masalah yang rumit:",options:["'Solusi mana yang tidak akan pernah salah dalam keadaan apa pun, sekarang maupun nanti setelah keadaan berubah?'","'Solusi mana yang paling mahal harganya, karena yang mahal pasti paling bagus dan paling cepat berhasil?'","'Solusi mana yang paling masuk akal untuk DICOBA dulu dan kita pelajari hasilnya', bukan 'solusi mana yang pasti benar selamanya'"],answer:2,explain:"Untuk masalah rumit, memilih berarti memilih titik awal yang baik untuk belajar, bukan mengunci jawaban akhir.",hint:"Apakah kamu memilih 'jawaban final' atau 'langkah pertama yang bisa dipelajari'?"},
{n:80,type:"open",micro:"Menemukan cacat dalam pilihan populer",q:"Kelas hendak memilih solusi 'denda Rp2.000 bagi yang terlambat, uang dipakai untuk kas kelas'. Solusi ini populer. Tuliskan minimal 3 kelemahan atau risiko yang mungkin terlewat, dan usulkan satu penyesuaian atau alternatif.",explain:"Jawaban baik: mengenali bahwa solusi menangani gejala bukan akar, isu keadilan, efek pada hubungan/norma, beban administrasi, dan menawarkan perbaikan.",hint:"Tanyakan: apakah ini menyentuh penyebab? Adil untuk siapa? Efek samping apa? Beban tambahan apa?",sample:"Kelemahan: (1) tidak menyentuh penyebab keterlambatan (transport, bangun kesiangan) — hanya menghukum gejala; (2) tidak adil bagi siswa yang terlambat karena hal di luar kendali (macet, jemputan) vs yang benar-benar lalai; (3) bisa menciptakan hubungan buruk 'kelas vs siswa' dan siswa yang mampu membayar merasa 'boleh' terlambat; (4) mengelola uang denda menambah beban bendahara dan bisa memicu sengketa. Penyesuaian: ganti denda uang dengan 'kompensasi waktu' (piket tambahan ringan) dan kecualikan alasan yang bisa diverifikasi; sertai dengan mendata penyebab keterlambatan agar bisa dibantu (misalnya atur ulang kelompok berangkat bersama)."},
{n:81,type:"mcq",micro:"Solusi berlapis",q:"Untuk masalah rumit (misalnya 'perundungan di sekolah'), solusi yang paling mungkin efektif biasanya...",options:["Beberapa tindakan yang saling melengkapi (pencegahan + aturan jelas + dukungan korban + pendidikan) daripada satu 'peluru ajaib'","Satu aturan tegas saja","Mengabaikannya"],answer:0,explain:"Masalah kompleks jarang tuntas dengan satu solusi. Portofolio tindakan yang bekerja pada beberapa titik lebih realistis.",hint:"Bisakah satu tindakan tunggal mengatasi masalah dengan banyak penyebab?"},
{n:82,type:"mcq",micro:"Memilih portofolio, bukan satu",q:"Kalau anggaran memungkinkan mencoba 2 dari 5 ide sekaligus, cara memilih pasangan yang baik:",options:["Dua yang identik","Pilih dua yang saling melengkapi (menangani penyebab berbeda) dan tidak saling mengganggu, bukan dua yang mirip","Dua yang paling mahal"],answer:1,explain:"Saat mencoba beberapa solusi bersamaan, keberagaman dan saling melengkapi lebih berharga daripada mengulang pendekatan yang sama.",hint:"Apakah dua solusi yang menangani penyebab yang sama menambah banyak?"},
{n:83,type:"tf",micro:"Menghasilkan ide bersama pihak yang terdampak",q:"Benar atau Salah: Orang yang akan terkena dampak solusi sebaiknya tidak dilibatkan dalam menghasilkan ide karena mereka terlalu dekat dengan masalah untuk berpikir jernih.",answer:false,explain:"Justru melibatkan mereka cenderung menghasilkan solusi yang lebih tepat (mereka membawa pengetahuan praktis) DAN lebih diterima (keterlibatan membangun rasa memiliki).",hint:"Siapa yang paling tahu apa yang akan berhasil dalam praktik, dan siapa yang harus menjalankannya?"},
{n:84,type:"mcq",micro:"Kriteria yang bertentangan",q:"Ide A: cepat & murah tapi solusi sementara. Ide B: lambat & mahal tapi permanen. Kriteria 'cepat' dan 'permanen' bertentangan. Pendekatan matang:",options:["Pilih salah satu dan lupakan yang lain","Batalkan keduanya","Pertimbangkan menggabungkan: jalankan A sekarang untuk meredakan, sambil mengerjakan B untuk jangka panjang"],answer:2,explain:"Kriteria yang bertentangan sering bisa didamaikan dengan solusi bertahap: tindakan cepat + tindakan permanen berjalan bersama.",hint:"Apakah kamu harus memilih antara 'sekarang' dan 'permanen', atau bisa keduanya?"},
{n:85,type:"order",micro:"Proses lengkap menghasilkan & memilih",q:"Urutkan seluruh proses dari masalah yang dipahami sampai keputusan siap dilaksanakan.",items:["Hasilkan banyak ide dengan beberapa teknik & sudut pandang","Rapikan, kelompokkan, dan saring kasar menjadi 4–6 kandidat","Tetapkan kriteria (dan bobot), nilai kandidat, kenali trade-off","Pilih (satu, gabungan, atau portofolio) + tetapkan ukuran keberhasilan + rencana uji coba"],answer:[0,1,2,3],explain:"Melebar (banyak ide) → menyempit (kandidat) → menilai (kriteria & trade-off) → memutuskan (dengan ukuran & uji coba).",hint:"Fase melebar selalu sebelum fase menyempit."},
{n:86,type:"mcq",micro:"Menilai di bawah ketidakpastian besar",q:"Untuk masalah dengan banyak hal tidak diketahui, kriteria pemilihan yang berguna ditambahkan:",options:["'Seberapa banyak yang bisa kita pelajari dari mencoba ini' dan 'seberapa mudah dibatalkan' — utamakan solusi yang informatif dan reversibel","'Seberapa permanen solusinya' dan 'seberapa sulit dibatalkan' — utamakan solusi yang paling kaku dan tidak mungkin diubah lagi setelah dijalankan","'Seberapa mahal solusinya' dan 'seberapa megah kelihatannya' — utamakan solusi yang termahal karena pasti paling meyakinkan bagi semua orang"],answer:0,explain:"Di bawah ketidakpastian tinggi, solusi yang mengajarkan sesuatu dan mudah ditarik kembali lebih bijak daripada komitmen besar yang kaku.",hint:"Kalau kamu tidak yakin, solusi seperti apa yang paling aman dicoba?"},
{n:87,type:"mcq",micro:"Solusi yang bergantung pada perubahan perilaku banyak orang",q:"Ide yang butuh 'semua siswa mengubah kebiasaan sekaligus' cenderung sulit. Cara meningkatkan peluang:",options:["Beri hukuman berat","Buat perilaku baru mudah dilakukan (kurangi hambatan), terlihat (contoh & norma), dan bermanfaat langsung bagi pelakunya","Andalkan pengumuman sekali"],answer:1,explain:"Perubahan perilaku massal lebih berhasil bila jalur yang diinginkan dibuat mudah, terlihat normal, dan menguntungkan.",hint:"Mengapa orang mengadopsi kebiasaan baru — karena disuruh, atau karena mudah dan berguna?"},
{n:88,type:"tf",micro:"Keputusan bisa ditinjau",q:"Benar atau Salah: Setelah sebuah solusi dipilih dan dijalankan, meninjaunya kembali dan menggantinya berarti pemilihan awal telah gagal, jadi sebaiknya dihindari.",answer:false,explain:"Memilih bukan akhir. Memantau, mengevaluasi, dan menyesuaikan solusi agar tetap relevan dengan keadaan yang berubah adalah bagian normal dari pemecahan masalah, bukan tanda kegagalan.",hint:"Apakah nakhoda yang mengubah haluan karena badai telah gagal?"},
{n:89,type:"mcq",micro:"Ketika semua kandidat buruk",q:"Kalau setelah dinilai, semua kandidat tampak buruk, kemungkinan besar...",options:["Pilih saja yang paling tidak buruk di antaranya lalu berhenti berpikir, karena mencari ide lagi pasti sia-sia","Masalahnya memang tidak bisa dipecahkan oleh siapa pun, sehingga lebih baik dihentikan dan dilupakan saja","Kamu perlu kembali menghasilkan ide (mungkin dengan teknik/peserta baru) atau meninjau ulang definisi masalahnya"],answer:2,explain:"Daftar kandidat yang semuanya lemah sering berarti ruang ide belum digali cukup, atau masalahnya salah dirumuskan.",hint:"Apakah kamu sudah mencoba semua sudut, atau masalahnya sendiri yang perlu dilihat ulang?"},
{n:90,type:"mcq",micro:"Menyampaikan keputusan",q:"Setelah kelompok memilih solusi, menjelaskan ke pihak lain sebaiknya menyertakan...",options:["Apa yang dipilih, kriteria yang dipakai, dan mengapa kandidat lain tidak dipilih — agar keputusan bisa dipahami dan didukung","Hanya kalimat 'kami sudah memutuskan' saja, karena penjelasan lebih panjang akan memancing perdebatan baru lagi","Menyembunyikan alasannya, karena pihak lain tidak perlu tahu bagaimana keputusan itu diambil oleh kelompok"],answer:0,explain:"Keputusan yang dijelaskan dengan alasannya lebih mudah didukung dan lebih tahan terhadap keberatan belakangan.",hint:"Mana yang lebih meyakinkan: 'ini keputusannya' atau 'ini keputusannya, dan begini pertimbangannya'?"},
{n:91,type:"mcq",micro:"Solusi dan sumber daya berkelanjutan",q:"Solusi 'perpustakaan buka lebih lama, dijaga guru bergiliran setelah jam kerja' mungkin bagus tapi perlu dinilai keberlanjutannya karena...",options:["Keberlanjutan tidak penting sama sekali untuk dinilai, karena yang terpenting solusinya terdengar bagus dan membuat orang senang saat diumumkan pertama kali","Bergantung pada kerelaan guru bekerja ekstra tanpa henti — bisa tidak bertahan; perlu cara yang tidak membebani segelintir orang terus-menerus","Guru pasti selalu bersedia bekerja tambahan kapan saja tanpa merasa lelah, sehingga solusi itu aman dijalankan selamanya tanpa perlu cara lain"],answer:1,explain:"Solusi yang bertumpu pada pengorbanan berkelanjutan segelintir orang cenderung runtuh. Nilai apakah ia bisa berjalan tanpa membakar habis pelaksananya.",hint:"Apa yang terjadi setelah 3 bulan guru bergiliran lembur?"},
{n:92,type:"tf",micro:"Menghasilkan & memilih adalah keterampilan yang bisa dilatih",q:"Benar atau Salah: Kemampuan menghasilkan banyak ide bagus dan memilih dengan bijak berkembang dengan latihan dan meninjau hasil keputusan sebelumnya.",answer:true,explain:"Setiap siklus 'hasilkan–pilih–jalankan–tinjau' menajamkan intuisi tentang ide apa yang berhasil dan kriteria apa yang penting.",hint:"Apakah orang menjadi pengambil keputusan yang lebih baik dengan pengalaman?"},
{n:93,type:"mcq",micro:"Menghindari analisis berlebihan",q:"Tanda kamu sudah cukup menganalisis dan waktunya memutuskan:",options:["Kamu sudah menganalisis selama berminggu-minggu","Semua orang lelah","Kandidat teratas sudah cukup jelas, dan informasi tambahan kecil kemungkinannya mengubah pilihan"],answer:2,explain:"Ketika analisis tambahan tidak lagi mengubah peringkat kandidat, itu sinyal untuk memutuskan dan mulai.",hint:"Apakah info berikutnya kemungkinan akan mengubah pilihanmu?"},
{n:94,type:"open",micro:"Menghasilkan & memilih untuk masalah nyata",q:"Pilih masalah nyata berskala sedang di sekolah/lingkunganmu. Lakukan: (1) nyatakan masalah & akarnya secara singkat, (2) hasilkan minimal 8 ide dengan minimal 2 teknik berbeda, (3) saring jadi 3 kandidat, (4) buat matriks keputusan (3–4 kriteria berbobot, skor), (5) sebutkan trade-off pemenang, (6) tetapkan ukuran keberhasilan & rencana uji coba kecil.",explain:"Jawaban baik menjalankan seluruh siklus: masalah+akar, ide dari beberapa teknik, penyaringan, matriks berbobot yang benar hitungannya, trade-off, dan ukuran + uji coba.",hint:"Pastikan idenya benar-benar beragam; kriteria matriks harus yang membedakan kandidat.",sample:"Contoh ringkas — Masalah: koridor licin & sering ada yang jatuh saat hujan; akar: air terbawa masuk dari sepatu + tidak ada keset + lantai jenis mengkilap. (2) Teknik 'balik masalah' → daftar penyebab → ide: keset panjang di tiap pintu, area lepas-sepatu, tanda 'hati-hati licin', pel rutin tiap 30 menit saat hujan, karpet karet sepanjang koridor, atap kanopi di jalur masuk. Teknik 'tiru tempat lain' (mal/masjid) → rak sepatu + lantai anti-slip + petugas kebersihan siaga. (3) Kandidat: A keset panjang + tanda peringatan (murah); B karpet karet sepanjang koridor (sedang); C jadwal pel + petugas siaga saat hujan (butuh koordinasi). (4) Kriteria (bobot): efektivitas mengurangi jatuh (×3), biaya (×2), kemudahan pelaksanaan (×2), keberlanjutan (×1). A: 3,5,4,4 → 9+10+8+4=31. B: 4,3,3,3 → 12+6+6+3=27. C: 4,4,2,2 → 12+8+4+2=26. (5) Trade-off A: paling mudah & murah tapi efektivitasnya sedang — mungkin perlu dilengkapi B nanti. (6) Ukuran: jumlah laporan tergelincir per minggu turun; uji coba: pasang A di 2 pintu tersibuk selama 2 minggu musim hujan, catat kejadian, bandingkan dengan pintu tanpa keset."},
{n:95,type:"mcq",micro:"Solusi yang menyesuaikan diri",q:"Solusi yang menyertakan 'kita akan tinjau tiap bulan dan sesuaikan' lebih kuat untuk masalah kompleks karena...",options:["Mengakui bahwa kita tidak tahu segalanya di awal dan membangun mekanisme perbaikan ke dalam solusi itu sendiri","Berarti solusinya lemah dan belum matang, sehingga perlu ditinjau karena penyusunnya sendiri ragu pada rencananya","Menunda keputusan selamanya, karena setiap bulan solusi yang sudah dipilih akan diganti dengan yang baru lagi"],answer:0,explain:"Membangun peninjauan berkala ke dalam solusi mengubahnya dari 'tebakan sekali jadi' menjadi proses yang belajar.",hint:"Untuk masalah yang kita tidak sepenuhnya pahami, apa yang lebih bijak daripada 'tetapkan sekali dan lupakan'?"},
{n:96,type:"mcq",micro:"Peran intuisi setelah analisis",q:"Setelah matriks memberi 2 kandidat hampir seri, memakai intuisi ('yang B terasa lebih pas untuk kelas kita') ...",options:["Harus selalu mengalahkan matriks","Bisa dibenarkan sebagai penentu akhir, terutama kalau intuisi itu berdasar pengalaman nyata dengan konteksnya","Selalu salah"],answer:1,explain:"Ketika analisis tidak bisa memisahkan dua pilihan, penilaian berpengalaman terhadap konteks adalah pelengkap yang sah — bukan pengganti analisis.",hint:"Kapan intuisi paling berguna: menggantikan analisis, atau memutuskan saat analisis seri?"},
{n:97,type:"tf",micro:"Tidak memilih juga sebuah pilihan",q:"Benar atau Salah: Menunda keputusan tanpa batas waktu, atau membiarkan keadaan memutuskan sendiri, sebenarnya juga merupakan sebuah pilihan — dengan konsekuensinya sendiri.",answer:true,explain:"'Tidak memutuskan' bukan menghindari konsekuensi; ia memilih apa pun yang terjadi kalau tidak ada yang bertindak.",hint:"Apa yang terjadi pada masalah kalau tidak ada yang memilih solusi?"},
{n:98,type:"mcq",micro:"Menutup fase pemilihan",q:"Setelah solusi dipilih, langkah yang menghubungkan ke pelaksanaan:",options:["Umumkan saja pilihan itu kepada semua orang lalu berhenti di situ, karena sisanya akan berjalan dengan sendirinya tanpa perlu ditugaskan atau dievaluasi","Kembali menghasilkan ide-ide baru dari awal lagi dan lagi, walaupun solusi yang sudah dipilih belum pernah dicoba maupun dibuat rencananya","Ubah solusi terpilih menjadi rencana konkret (langkah, PJ, tenggat, sumber daya) dan tetapkan kapan & bagaimana hasilnya dievaluasi"],answer:2,explain:"Solusi terpilih baru bernilai kalau diterjemahkan menjadi rencana yang bisa dijalankan dan dievaluasi.",hint:"Apa yang mengubah 'kita pilih A' menjadi 'A sedang berjalan'?"},
{n:99,type:"mcq",micro:"Ringkasan: menghasilkan & memilih",q:"Rangkuman paling tepat:",options:["Hasilkan banyak ide beragam dengan menunda penilaian; saring menjadi kandidat; nilai dengan kriteria yang mencerminkan apa yang penting, sadar akan trade-off dan bias; pilih untuk dicoba dengan ukuran keberhasilan yang jelas; tinjau dan sesuaikan","Ambil saja ide pertama yang muncul di kepala lalu jalankan secepatnya, tanpa perlu menyaring menjadi kandidat, membandingkannya dengan kriteria, memikirkan trade-off dan bias, ataupun menetapkan ukuran keberhasilan dan jadwal tinjauannya","Analisis terus-menerus selamanya tanpa pernah memilih satu pun, sambil menunggu sampai ditemukan solusi yang benar-benar sempurna di semua kriteria dan disukai oleh semua orang, sehingga tidak ada satu pun ide yang sempat dicoba"],answer:0,explain:"Proses: melebar (ide) → menyempit (kandidat) → menilai (kriteria, trade-off, bias) → memutuskan (dengan ukuran) → meninjau.",hint:"Gabungkan: banyak ide → kandidat → nilai jujur → pilih & ukur → tinjau."},
{n:100,type:"open",micro:"Kapstone: dari ide ke keputusan yang bisa dipertahankan",q:"Ambil keputusan nyata yang harus kamu/kelompokmu ambil. Lakukan seluruh proses dan tuliskan 'catatan keputusan': (1) masalah & tujuan, (2) daftar ide yang dipertimbangkan (min. 8), (3) kandidat terpilih (3) + alasan yang lain gugur, (4) kriteria + bobot + skor + total, (5) pilihan akhir + trade-off yang diterima + bias yang kamu waspadai, (6) ukuran keberhasilan, rencana uji coba, dan kapan keputusan akan ditinjau ulang.",explain:"Kapstone menghasilkan artefak nyata (catatan keputusan) yang menunjukkan seluruh proses dan bisa dipertahankan di hadapan orang lain.",hint:"Tulis seolah kamu harus menjelaskan dan mempertahankan keputusan ini ke guru minggu depan.",sample:"Format 'catatan keputusan' yang baik terisi lengkap keenam bagian, dengan: ide yang benar-benar beragam; alasan gugur yang menyebut kriteria (bukan selera); matriks yang hitungannya benar dan kriterianya relevan; pengakuan jujur atas trade-off pilihan (apa yang dikorbankan) dan bias yang mungkin memengaruhi (mis. 'ini ide milikku, jadi aku minta 2 orang lain menilai'); ukuran keberhasilan yang terukur; uji coba kecil sebelum skala penuh; dan tanggal/pemicu peninjauan ('tinjau setelah 3 minggu atau bila ada laporan efek samping'). Contoh singkat untuk 'memilih tema & format buletin kelas': ide 8+ (cetak/digital/campuran, mingguan/bulanan, per-rubrik, dll.); kandidat: buletin digital bulanan, papan buletin fisik mingguan, grup pengumuman + rekap bulanan; kriteria (bobot): jangkauan (×3), beban kerja tim (×3), biaya (×2), keterlibatan pembaca (×2); dst."},
];
